mapper.select:
SELECT COUNT(*)
FROM routine_results rr
         JOIN enrollments e ON rr.enrollment_id = e.enrollment_id
WHERE e.training_id = #{trainingId}
  AND e.user_id = #{userId}
  AND rr.status = TRUE

mapper.update:
UPDATE enrollments
SET progress = #{progress}
WHERE training_id = #{trainingId}
  AND user_id = #{userId}
